import React, { useEffect, useRef } from 'react';
import servicesData from "./ServicesData";
import classes from './Services.module.scss';

const Services = () => {

  const getRandomAnimationDuration = () => {
    return Math.random() * 5 + 5;
  };

  return (
    <div className={classes.servicePage}>
      {servicesData.map((section, index) => (
        <div className={classes.serviceSection} key={index}>
          <img
            src="/img/AudioWave.png"
            alt="Audio Wave"
            className={classes.audioWave}
          />
          <h2 className={classes.sectionTitle}>{section.title}</h2>

          <div className={classes.serviceItems}>
            {section.items.map((item, itemIndex) => {
              const animationDuration = getRandomAnimationDuration();

              return (
                <h3
                  key={itemIndex}
                  className={classes.serviceName}
                  style={{ animationDuration: `${animationDuration}s` }}
                >
                  {item.name}
                </h3>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
};

export default Services;
